const crypto = require('crypto');

const headers = $input.item.json.headers || {};
const signature = headers['x-lendloop-signature'];
const timestamp = parseInt(headers['x-lendloop-timestamp'], 10);
const eventId = headers['x-lendloop-event-id'];
const body = $input.item.json.body || {};
const rawBody = $input.item.json.rawBody || JSON.stringify(body);

const secret = $env.CONVEX_N8N_HMAC_SECRET;
if (!secret) {
  return [{ json: { isValid: false, reason: 'CONVEX_N8N_HMAC_SECRET environment variable is missing' } }];
}

// 1. Check required headers
if (!signature || !timestamp || !eventId) {
  return [{ json: { isValid: false, reason: 'Missing signature, timestamp, or eventId header' } }];
}

// 2. Validate timestamp freshness (5 minutes tolerance = 300,000 ms)
const now = Date.now();
const diff = Math.abs(now - timestamp);
if (diff > 300000) {
  return [{ json: { isValid: false, reason: `Timestamp expired (drift: ${diff}ms > 300000ms)` } }];
}

// 3. Formulate canonical string: timestamp.eventId.rawBody
const canonical = `${timestamp}.${eventId}.${rawBody}`;
const expectedSignature = crypto.createHmac('sha256', secret).update(canonical).digest('hex');

// 4. Constant-time comparison
const sigBuffer = Buffer.from(signature, 'hex');
const expectedBuffer = Buffer.from(expectedSignature, 'hex');

if (sigBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
  return [{ json: { isValid: false, reason: 'HMAC signature mismatch' } }];
}

return [{ json: { isValid: true, eventId, timestamp, payload: body.payload || body } }];

const p = $input.item.json.payload || {};
const eventId = $input.item.json.eventId;

const notification = {
  eventId,
  recipient: p.lenderEmail || p.borrowerEmail || 'neighbor@community.local',
  subject: `LendLoop Notification: ${p.toolName || 'Tool Request'}`,
  message: `Tool: ${p.toolName}\nStatus: ${p.newStatus || 'Requested'}\nDates: ${p.startDate || ''} to ${p.endDate || ''}\nNote: ${p.note || 'None'}`,
  sentAt: new Date().toISOString()
};

console.log('[LendLoop Notification Dispatched]', JSON.stringify(notification));
return [{ json: { ...notification, deliverySuccess: true } }];
